<?php
/* Built-in courses for the learning platform (v30) and the templates behind "Create a live project".
   Lesson bodies use a small markdown: blank-line paragraphs, "## " headings, "- " bullets, **bold**, *italics*,
   [text](https://link). Quiz items: mc (one answer), multi (several), tf, fill (typed answer, any of a), num
   (a number), order (put the steps in order), match (pairs), scramble (unscramble a term). Admins edit everything
   under Admin > Learning; "Restore built-in course" brings a course back to this text. Reviewed October 2026. */
declare(strict_types=1);

function learnDefaultCourses(): array
{
    $mc = fn(string $q, array $o, int $a, string $why = '') => ['ty' => 'mc', 'q' => $q, 'o' => $o, 'a' => $a, 'why' => $why];
    $multi = fn(string $q, array $o, array $a, string $why = '') => ['ty' => 'multi', 'q' => $q, 'o' => $o, 'a' => $a, 'why' => $why];
    $tf = fn(string $q, bool $a, string $why = '') => ['ty' => 'tf', 'q' => $q, 'a' => $a, 'why' => $why];
    $fill = fn(string $q, array $a, string $why = '') => ['ty' => 'fill', 'q' => $q, 'a' => $a, 'why' => $why];
    $num = fn(string $q, float $a, string $why = '', float $tol = 0) => ['ty' => 'num', 'q' => $q, 'a' => $a, 'tol' => $tol, 'why' => $why];
    $order = fn(string $q, array $o, string $why = '') => ['ty' => 'order', 'q' => $q, 'o' => $o, 'why' => $why];
    $match = fn(string $q, array $pairs, string $why = '') => ['ty' => 'match', 'q' => $q, 'pairs' => $pairs, 'why' => $why];
    $scr = fn(string $q, string $a, string $hint = '') => ['ty' => 'scramble', 'q' => $q, 'a' => $a, 'hint' => $hint];
    $L = fn(string $id, string $t, string $body, array $quiz = []) => ['id' => $id, 't' => $t, 'body' => $body, 'quiz' => $quiz];
    $M = fn(string $id, string $t, array $ls) => ['id' => $id, 't' => $t, 'ls' => $ls];

    return [
        // ------------------------------------------------------------------ v34: security awareness (yearly, staff)
        ['id' => 'security', 't' => 'Security awareness at StratEdge', 'desc' => 'The yearly course for everyone at StratEdge: why a staffing firm is a target, how phishing, fake bank-change requests and fake candidates work, passphrases, two-step sign-in and passkeys, handling resumes, immigration papers and pay data, safe devices, AI tools, and what to do in the first hour of an incident. About 25 minutes, with short quizzes.', 'cat' => 'Security', 'level' => 'Essential', 'min' => 25, 'pass' => 80, 'cert' => false, 'req' => ['staff'], 'pub' => true, 'ord' => 5, 'mods' => [
            $M('m1', 'Why we are a target', [
                $L('l1', 'What we hold, and who wants it', "A staffing firm holds exactly what criminals want, for thousands of people: **Social Security numbers**, dates of birth, passport and visa copies, **Form I-9** documents, **bank accounts** for direct deposit, pay records and home addresses, plus resumes and client contracts.\n\n- **Identity thieves** use an SSN, date of birth and address to open credit in someone's name.\n- **Payroll fraudsters** change a consultant's bank account so the next paycheck lands in their account.\n- **Fake candidates** (sometimes with AI-generated faces and voices) try to get placed at clients to reach the client's systems.\n- **Ransomware groups** lock files and threaten to publish them.\n\nWhen it goes wrong, people lose money and status documents, clients lose trust, and the law sets clocks: in some states we must notify affected residents within 30 days, regulators within days, and for people in the EU the authority within **72 hours**. Most incidents start with one person clicking, typing or sending something - which is why this course exists.", [
                    $multi('Which of these does StratEdge hold that criminals value? (choose all that apply)', ['Social Security numbers and dates of birth', 'Bank accounts for direct deposit', 'Passport, visa and I-9 documents', 'The office coffee order'], [0, 1, 2]),
                    $tf('Most security incidents begin with a technical flaw that staff could not have noticed.', false, 'Most start with a person clicking a link, approving a sign-in or sending data to the wrong place.'),
                ]),
                $L('l2', 'How we label information', "Every piece of information falls in one of four classes (the Data Classification policy):\n\n- **Public** - the website, published job posts.\n- **Internal** - procedures, internal announcements, rate cards. Not for outsiders.\n- **Confidential** - resumes, client requirements and contracts, pay rates, candidate submissions. Only people who need it for their work.\n- **Restricted** - SSNs and tax IDs, bank accounts, immigration and I-9 documents, ID copies, background checks, health information, passwords and keys. Kept in the portal (encrypted), never in email, chat, spreadsheets or personal drives.\n\nWhen unsure, treat it as the higher class and ask.", [
                    $match('Match each item to its class.', [['A bank account number for direct deposit', 'Restricted'], ['A consultant\'s resume', 'Confidential'], ['A published job post', 'Public'], ['The internal holiday calendar', 'Internal']]),
                    $mc('Where may a copy of someone\'s H-1B approval notice (I-797) be kept?', ['In your email so it is easy to find', 'In the portal (Documents or Compliance), where it is encrypted', 'In a shared spreadsheet with the other visa dates', 'On your laptop desktop'], 1),
                ]),
            ]),
            $M('m2', 'Phishing, fraud and fake people', [
                $L('l3', 'Spotting phishing (email, text, calls and QR codes)', "Phishing imitates someone you trust to make you click, sign in, open, pay or reveal. The signs:\n\n- **Urgency or fear** - \"your mailbox closes today\", \"payment overdue\", \"the CEO needs this now\".\n- **A sender or link that is almost right** - stratedge-itconsulting.com, a display name that hides a free webmail address, a link whose real address (hover or long-press) is elsewhere.\n- **Unexpected attachments** - invoices, \"scanned documents\", HTML files, password-protected zips.\n- **Requests to sign in** from an email link. Go to the portal by typing the address or using your bookmark instead.\n- **QR codes** in emails or posters that lead to sign-in pages (\"quishing\").\n- **Texts and calls** claiming to be IT, the bank or a client - and voices that can now be cloned from a short recording.\n\nIf something feels off, do not click, do not reply: report it (Sign-in & security > Report a security concern). Reporting a false alarm is fine; a missed real one is not.", [
                    $multi('Which are warning signs of phishing? (choose all that apply)', ['A sender domain one letter different from ours', 'Pressure to act within the hour', 'An email from a colleague you were expecting, sent from our usual domain, with no links', 'A QR code asking you to re-enter your password'], [0, 1, 3]),
                    $mc('An email says your portal password expires today and offers a "Keep my password" button. What do you do?', ['Click it quickly before it expires', 'Report it; if you are worried, open the portal by typing the address yourself', 'Forward it to all staff as a warning', 'Reply asking if it is real'], 1, 'StratEdge does not expire passwords on a schedule; sign in only by typing the address or using your bookmark.'),
                ]),
                $L('l4', 'Bank-change requests and payroll diversion', "One of the most common frauds against staffing firms: an email, text or call - seemingly from a consultant or employee - asks to change the bank account for their pay. It often comes from a lookalike or hacked mailbox, right before payroll.\n\n- **We never change bank details from an email, chat or phone call.** People change their own account in the portal (Earnings > Direct deposit), after signing in with two-step sign-in; the change is logged and a prenote test follows.\n- If someone asks you to change it for them, tell them to do it in the portal, and **call them back on the number already on file** (not one in the message) to confirm the request was theirs.\n- The same rule applies to vendors and clients: a new remittance account for an invoice is verified by a call-back to a known contact before any payment.\n- Report every such request, even when it turns out to be genuine.", [
                    $order('Put the response to an emailed bank-change request in order.', ['Do not change anything from the email', 'Call the person back on the number already on file', 'Ask them to make the change themselves in the portal', 'Report the request (Sign-in & security > Report a security concern)']),
                    $tf('A bank-change request from a consultant\'s usual email address can be trusted.', false, 'Mailboxes get hacked; the change is made by the person in the portal and confirmed by a call-back.'),
                ]),
                $L('l5', 'Fake candidates and impersonation', "Staffing firms now see candidates who are not who they claim: stolen identities, proxy interviewers, AI-generated faces or voices, and people placed at a client to steal data.\n\n- Check that the person on the video call matches the ID and the resume photo; ask them to turn their head, or to hold up the ID next to their face, if something looks off (lag, blurring around the face, lips out of sync).\n- Use the portal's verification steps (work authorization, ID, references) before submission, and the screening agent's warnings.\n- Never move a candidate forward because \"the client is in a hurry\" when checks are incomplete.\n- Impersonation runs the other way too: people may call pretending to be a client manager, a vendor or an immigration attorney to get a consultant's documents. Verify through a contact you already know.", [
                    $multi('Which are signs a video interview may be fake? (choose all that apply)', ['Lips out of sync with the voice', 'The face blurs when the person turns their head', 'The person asks a clarifying question', 'The person on camera does not match the ID photo'], [0, 1, 3]),
                ]),
            ]),
            $M('m3', 'Your accounts', [
                $L('l6', 'Passphrases, password managers and two-step sign-in', "- **Long beats complicated.** Use a passphrase of four or more unrelated words (at least 15 characters if two-step sign-in is off). The portal refuses passwords seen in data breaches.\n- **Never reuse** a password from another site. When another site is breached, attackers try the same email and password everywhere.\n- **Use a password manager** (the one StratEdge provides, or a reputable one) to create and fill unique passwords.\n- **Two-step sign-in** is required for administrators, HR and accounting and recommended for everyone. **Passkeys** (Face ID, fingerprint, Windows Hello, a security key) are the strongest: they cannot be phished, because they only work on the real site.\n- Keep your **backup codes** somewhere safe and offline.\n- Lock your screen when you step away (Windows + L, Control + Command + Q on a Mac).", [
                    $mc('Which is the strongest password for the portal?', ['Summer2026!', 'P@ssw0rd123', 'copper lantern meadow harbor', 'StratEdge2026'], 2, 'A long passphrase of unrelated words is both strong and easy to remember.'),
                    $tf('A passkey cannot be used on a fake lookalike website.', true, 'Passkeys are tied to the real site address, which is why they resist phishing.'),
                ]),
                $L('l7', 'Codes, approvals and sign-in alerts', "- **Never share a sign-in code** - not with IT, not with a manager, not with \"StratEdge support\". Nobody legitimate asks for it; the portal never does.\n- If you get a code or a passkey prompt you did not ask for, someone has your password: **do not approve it**, change your password and report it.\n- When the portal emails you about a **sign-in from a new device** that was not you, change your password, use *Sign out everywhere else* under Sign-in & security, and report it.\n- Check *Recent sign-ins* now and then.\n- Leaving StratEdge or changing roles? Access is removed or reduced the same day; never keep using a former colleague's login.", [
                    $mc('Someone calls from "StratEdge IT" and asks for the 6-digit code that just arrived on your phone. You...', ['Read it out, since IT asked', 'Refuse, hang up, change your password and report it', 'Send it by text instead', 'Give it but change it later'], 1),
                    $order('You receive a "new device sign-in" email for a sign-in that was not you. Put the steps in order.', ['Change your password', 'Sign out everywhere else (Sign-in & security)', 'Check Recent sign-ins and your second steps', 'Report it as a security concern']),
                ]),
            ]),
            $M('m4', 'Handling people\'s data every day', [
                $L('l8', 'Share through the portal, not by email or chat', "- Resumes go to clients through **submissions** in the portal, after the candidate agreed to be represented (right to represent). Remove anything a client does not need (SSN, date of birth, full address, visa document numbers).\n- **Never send** SSNs, bank details, I-9 or immigration documents by email, text, WhatsApp or personal cloud links. If someone sends them to you, upload them to the portal and delete the message (and empty the trash).\n- Before sending, check the recipient (autocomplete picks the wrong person), and use BCC for bulk emails to vendors.\n- Download only what you need; delete local copies when done. Printouts of Restricted data are shredded, not binned.\n- Old candidate records are deleted automatically after the retention period; do not keep private copies \"just in case\".", [
                    $mc('A consultant emails you a photo of their passport. What do you do?', ['Keep it in your inbox for later', 'Upload it to their Documents in the portal, delete the email and empty the trash', 'Forward it to the client so they have it', 'Save it to your desktop'], 1),
                    $multi('What should be removed from a resume before it goes to a client? (choose all that apply)', ['Social Security number', 'Date of birth', 'Technical skills', 'Visa document numbers'], [0, 1, 3]),
                ]),
                $L('l9', 'AI tools and personal data', "AI assistants are useful, but anything you paste into a public AI tool may be stored, reviewed or used for training by its provider.\n\n- Use **StratEdge AI** inside the portal for resumes, emails and job descriptions: it is set up for our data and logs what it sends.\n- Never paste SSNs, bank details, immigration documents, health information or client confidential material into a public AI tool.\n- Check what AI writes: it can invent skills, dates or facts. A recruiter is always responsible for what is sent to a client or candidate.\n- AI-written outreach must still follow the email rules (opt-out, no misleading subject lines).", [
                    $tf('It is fine to paste a candidate\'s full resume, including their SSN, into a free public chatbot to reformat it.', false, 'Use StratEdge AI inside the portal, and never include Restricted data.'),
                ]),
            ]),
            $M('m5', 'Devices, remote work and incidents', [
                $L('l10', 'Safe devices and remote work', "- **Disk encryption on** (BitLocker on Windows, FileVault on a Mac), **automatic updates on**, a screen lock after 5 minutes, and antivirus (Microsoft Defender is fine).\n- Work data stays in the portal and company accounts, not on USB sticks or personal cloud drives.\n- On public Wi-Fi, use your phone's hotspot or the company VPN when one is provided; the portal always uses HTTPS.\n- Don't let family use your work device; lock it in the car trunk or carry it - never leave it visible.\n- **Lost or stolen device: report within the hour.** We can end its sessions and access remotely; the sooner, the better.", [
                    $multi('Which belong on every work laptop? (choose all that apply)', ['Disk encryption (BitLocker or FileVault)', 'Automatic updates', 'A screen lock', 'A sticky note with the passwords'], [0, 1, 2]),
                    $mc('Your laptop is stolen from your car on Saturday evening. When do you report it?', ['On Monday morning', 'Within the hour, through Report a security concern (or by phone to your manager)', 'Only if it had client data', 'No need if it had a password'], 1),
                ]),
                $L('l11', 'The first hour of an incident', "An incident is anything that may have exposed our or someone else's data or accounts: a clicked phishing link, a password typed into a fake page, a lost device, an email sent to the wrong person, a strange sign-in, ransomware notes, a vendor breach.\n\n- **Report at once**: Sign-in & security > Report a security concern, or call the security officer. Speed matters more than certainty.\n- **Don't investigate or clean up yourself**, don't delete emails or files, and don't contact the attacker. Disconnect a device from the network if ransomware appears.\n- Write down what happened and when, while you remember.\n- Don't discuss it outside the response team or on social media; legal notices go out through the company.\n- After it is closed, we change what allowed it - nobody is blamed for reporting.", [
                    $order('You typed your password into a page you now think was fake. Put the steps in order.', ['Report it right away', 'Change your password on the real portal', 'Sign out everywhere else', 'Write down what happened and when']),
                    $tf('If you clicked a phishing link, it is better to quietly delete the email than to report it.', false, 'Report it at once: we can block the site, check your account and warn others.'),
                    $mc('Who decides on notifying regulators, clients and the people affected?', ['The person who found the problem', 'The company, through the incident response team and counsel', 'Whoever posts first on social media', 'Nobody needs to be notified'], 1),
                ]),
            ]),
        ]],
        // ------------------------------------------------------------------ USCIS compliance
        ['id' => 'uscis', 't' => 'USCIS compliance for consultants', 'desc' => 'The rules that keep your status safe while you work through StratEdge: OPT and STEM OPT, H-1B at work, the green card path, address changes, Form I-9, travel and taxes. Built from the compliance hub; every lesson links to the primary source.', 'cat' => 'Compliance', 'level' => 'Essential', 'min' => 50, 'pass' => 70, 'cert' => true, 'req' => ['consultant', 'employee'], 'pub' => true, 'mods' => [
            $M('m1', 'Your status at a glance', [
                $L('l1', 'Visa, I-94 and status are three different things', "A **visa stamp** in your passport lets you ask to enter the United States. The **I-94** record that CBP creates when you enter says *how long* you may stay and in *which class*. Your **status** is the set of rules you live under while you are here (student, H-1B worker, dependent).\n\n- The stamp may expire while you are inside the U.S.; that alone does not affect your status.\n- The I-94 end date controls your stay - download it after every entry at [i94.cbp.dhs.gov](https://i94.cbp.dhs.gov/) and compare it with your I-797 approval or I-20.\n- If your passport expires before your petition end date, CBP admits you only to the passport date.\n\n## Since 15 September 2026: fixed dates for F-1 students\nNew F-1 admissions carry a fixed end date (the I-20 program end date, at most four years, plus 30 days) instead of \"duration of status\". Staying longer - including for OPT - needs an extension of stay on Form I-539. Students admitted under D/S before that date who file their OPT application by 18 March 2027 are exempt from the I-539.", [
                    $mc('Which document decides when your permission to stay in the U.S. ends?', ['The visa stamp in the passport', 'The I-94 admission record', 'The approval notice (I-797)', 'Your employment letter'], 1, 'The I-94 controls your stay; the stamp only lets you ask to enter.'),
                    $tf('An expired visa stamp means you are out of status.', false, 'Status comes from the I-94 and the rules of your class, not from the stamp.'),
                    $mc('Your passport expires six months before your H-1B approval ends. On re-entry CBP will most likely admit you until...', ['the I-797 end date', 'the passport expiry date', 'one year from entry', 'the LCA end date'], 1, 'CBP admits only to the passport expiry; renew the passport and fix the I-94 afterwards.'),
                    $fill('Under the 2026 rule, F-1 admission has a fixed end date instead of "duration of ______".', ['status'], 'Duration of status (D/S) ended for new admissions on 15 September 2026.'),
                ]),
                $L('l2', 'The ten-day rule and your immigration file', "Two habits prevent most problems.\n\n**Report within 10 days.** Every non-citizen must file Form AR-11 within 10 days of moving (online, free). F-1 students also update the SEVP Portal or their DSO within 10 days, and STEM OPT students report job changes in the same window. Tell HR the same day: payroll, Form I-9, state tax and the H-1B worksite check depend on it.\n\n**Keep a complete file.** Passport pages, every visa, every I-94, I-20s, EADs, I-797 receipts and approvals, LCAs, offer and client letters, the last three months of pay stubs, W-2s and tax returns. Scan them into *Compliance > Documents* with their expiry dates; later petitions ask for all of it.", [
                    $num('Within how many days of moving must Form AR-11 be filed?', 10, 'Ten days, under INA section 265.'),
                    $multi('Which belong in your immigration file? (choose all that apply)', ['Every I-94 record', 'Pay stubs', 'Your gym contract', 'I-797 approval notices', 'LCA copies'], [0, 1, 3, 4]),
                    $tf('Pay stubs prove that an H-1B worker was paid the LCA wage and maintained status.', true),
                ]),
            ]),
            $M('m2', 'OPT and STEM OPT', [
                $L('l3', 'Post-completion OPT: the 90-day clock', "Post-completion OPT gives 12 months of work related to your degree, at least 20 hours a week. Two numbers matter:\n\n- **10 days** to report each employer (name, address, dates, supervisor, how the job relates to your major) and your own address in the SEVP Portal or to your DSO.\n- **90 days** of unemployment in total. Every calendar day without qualifying work counts from the EAD start date - weekends and travel included.\n\nAfter OPT ends you have a grace period of 60 days (admitted under D/S) or 30 days (fixed-date admission) to leave, transfer or change status. You may not work during it unless cap-gap applies.", [
                    $num('How many days of unemployment are allowed during post-completion OPT?', 90),
                    $mc('You start a new job on OPT. By when must the SEVP Portal show it?', ['Within 10 days', 'Within 30 days', 'At the next 6-month report', 'Only if your DSO asks'], 0),
                    $tf('Days spent travelling abroad while unemployed do not count towards the 90 days.', false, 'They count; the clock runs on calendar days.'),
                ]),
                $L('l4', 'STEM OPT: 24 more months with reporting duties', "The 24-month STEM extension needs a qualifying STEM degree, an E-Verify employer, and a Form I-983 training plan with a named supervisor and learning objectives. Apply up to 90 days before your OPT EAD expires - and before it expires; filed on time, you may keep working up to 180 days while it is pending.\n\n## The reporting calendar\n- Changes within **10 days** (employer, address, title, duties, supervisor, hours, pay; a new or amended I-983 for job changes).\n- A **validation report** every **6 months** (6, 12, 18, 24 months after the STEM start date), due within 10 days of the mark.\n- A **self-evaluation** on Form I-983 page 5 at **12 months** and a **final evaluation** at **24 months** or within 10 days of leaving the employer.\n- Unemployment: **150 days** in aggregate, including the days used on post-completion OPT.\n\nSEVP terminates records automatically at 150 unemployment days or after 90 days without reported employer information. Your checklist in *Compliance* builds every one of these dates from your STEM start date.", [
                    $order('Put the STEM OPT application steps in order.', ['Employer completes and signs Form I-983', 'DSO issues the STEM OPT I-20', 'File Form I-765 within 60 days of the I-20 and before the OPT EAD expires', 'Work continues up to 180 days while USCIS decides']),
                    $num('Total unemployment days allowed across OPT and the STEM extension:', 150),
                    $match('Match each STEM OPT duty with its timing.', [['Validation report', 'every 6 months'], ['Self-evaluation on Form I-983', '12 and 24 months'], ['Report a job change', 'within 10 days'], ['Apply for the extension', 'up to 90 days before the EAD expires']]),
                    $mc('Which employer can sponsor STEM OPT training?', ['Any company that pays at least minimum wage', 'An E-Verify employer that supervises and trains you under a Form I-983', 'Any client where a staffing agency places you, with no training plan', 'Only universities'], 1),
                ]),
                $L('l5', 'Cap-gap and the weighted H-1B lottery', "When StratEdge files your H-1B change-of-status petition while your OPT or STEM OPT is still valid and the registration is selected, your F-1 status and work authorization extend automatically until **1 April** of the fiscal year (or until the petition is decided) - the cap-gap rule from the H-1B modernization rule in force since 17 January 2025. Ask your DSO for the cap-gap I-20 as proof for the Form I-9.\n\nSince 27 February 2026 the lottery is **weighted by wage level**: a Level IV offer gets four entries, Level III three, Level II two and Level I one; each person is selected at most once however many employers register them. Registration runs in March (4-19 March for FY 2027) with an earliest start of 1 October.", [
                    $mc('Cap-gap protection lasts until...', ['1 October', '1 April of the fiscal year, or the petition decision', '60 days after OPT ends', 'the end of the calendar year'], 1),
                    $num('How many lottery entries does a Level III wage offer receive?', 3),
                    $tf('If three employers register the same person, that person has three times the chance of selection.', false, 'Selection is beneficiary-centric: one selection per person; only the wage level changes the odds.'),
                ]),
            ]),
            $M('m3', 'H-1B at work', [
                $L('l6', 'Work where the LCA says, be paid what the LCA says', "Your H-1B is tied to the worksites on the certified **Labor Condition Application**. A new client site, or regular work from a home address outside the metropolitan area of the LCA, needs a new LCA and an **amended petition filed before you start there** (Matter of Simeio Solutions, 2015). Short placements of up to 30 days elsewhere are allowed; a move within the same metro area needs a posted notice, not a petition.\n\nYou must receive the required wage for all time, including time between projects decided by the employer - **benching is not allowed**. The employer pays the petition fees; early-termination penalties are prohibited; if dismissed early the employer owes return transportation. Complaints go to the Department of Labor on Form WH-4, and the law protects you from retaliation.", [
                    $mc('A client moves your project from Somerset, NJ to Dallas, TX for six months. What has to happen before you start in Dallas?', ['Nothing, the H-1B is national', 'A new LCA for Dallas and an amended petition filed first', 'An e-mail to the client', 'A new visa stamp'], 1),
                    $tf('Between projects an H-1B employer may stop paying until the next client is found.', false, 'Benching is prohibited; the required wage continues for employer-caused non-productive time.'),
                    $multi('Which costs may NOT be passed to the H-1B worker?', ['The petition filing fee', 'The ACWIA training fee', 'Premium processing the worker asks for personally', 'The employer\'s attorney fee for the petition'], [0, 1, 3]),
                ]),
                $L('l7', 'Extensions, the 240 days, the 60 days and the six years', "- **Extensions** can be filed up to **6 months** before your period ends; filed before expiry, you may keep working for the same employer up to **240 days** while it is pending.\n- **Grace period**: when a job ends you keep status for up to **60 consecutive days** (or until the I-94 expires, whichever is first) to have a new petition filed, change status or leave. No work in the grace period until USCIS *receives* a new petition (portability).\n- **Six years** is the H-1B maximum, minus days spent abroad (which you can recapture). Beyond that you need AC21: an approved I-140 (3-year extensions) or a PERM or I-140 filed 365+ days earlier (1-year extensions). Start the green card at least 18 months before the limit.\n- **Travel** needs a valid stamp, the original I-797, an LCA copy, recent pay stubs and an employment letter. The $100,000 payment under the September 2025 proclamation (extended to September 2027) targets new petitions for people outside the U.S.; it does not apply to extensions or changes of status inside the U.S., and its collection has been paused by a court order since June 2026 - check with HR before any trip.", [
                    $match('Match the number with the rule.', [['240 days', 'working while a timely extension is pending'], ['60 days', 'grace period after a job ends'], ['6 years', 'the H-1B maximum before AC21'], ['6 months', 'how early an extension can be filed']]),
                    $mc('When may you start working for a new H-1B employer?', ['After the approval notice arrives', 'When USCIS receives the new, non-frivolous petition', 'On the day you resign', 'After the visa interview'], 1),
                    $num('H-1B time is capped at how many years (before AC21 extensions)?', 6),
                ]),
            ]),
            $M('m4', 'The green card path', [
                $L('l8', 'PERM, I-140, I-485 - and what 180 days buys', "The employment-based green card has three steps: **PERM** labor certification (prevailing wage, recruitment, Form ETA-9089), the **I-140** immigrant petition (your priority date is the PERM filing date), and the **I-485** adjustment of status once the monthly Visa Bulletin shows your date is current.\n\n- An I-140 approved for **180 days** keeps your priority date even if the employer withdraws and supports 3-year H-1B extensions beyond six years.\n- An I-485 pending **180 days** lets you move to a same-or-similar job with a new employer (Supplement J).\n- While the I-485 is pending you can hold an EAD and Advance Parole. For renewal applications received after **30 October 2025** there is **no automatic extension** - file up to 180 days before expiry and keep your H-1B valid as a safety net. Do not travel without parole unless you hold valid H-1B/L-1 status and visa.\n- Adjustment needs clean status: INA 245(k) forgives at most 180 days of violations in total.", [
                    $order('Put the green card steps in order.', ['PERM labor certification (ETA-9089)', 'Form I-140 immigrant petition', 'Visa Bulletin date becomes current', 'Form I-485 adjustment of status']),
                    $mc('Your EAD from a pending I-485 expires in 5 months and you have not filed the renewal. What is true?', ['The old EAD extends automatically for 540 days', 'There is no automatic extension for renewals filed after 30 October 2025; file now and keep H-1B status as backup', 'You may keep working as long as the I-485 is pending', 'HR can extend it on the I-9'], 1),
                    $tf('After an I-485 has been pending 180 days you may change to a same-or-similar job with a new employer.', true),
                ]),
            ]),
            $M('m5', 'Address, Form I-9, travel and taxes', [
                $L('l9', 'Form I-9 and E-Verify', "You complete Section 1 of Form I-9 by your first day and show documents from the List of Acceptable Documents within **3 business days**. HR must reverify (Supplement B) **before** an EAD or I-94 expires; U.S. citizens and permanent residents are never reverified. Receipt notices count only where the rules allow it - a timely H-1B extension (240 days) or the STEM OPT 180-day extension with the I-20.\n\nE-Verify: a Tentative Nonconfirmation must be contested within 10 federal working days, and the employer may not act against you in the meantime. Never present documents that are not yours.", [
                    $num('Section 2 of Form I-9 must be completed within how many business days of the start date?', 3),
                    $tf('A permanent resident\'s green card expiry means HR must reverify their I-9.', false, 'Permanent residents are never reverified; the card expiry is not a work-authorization expiry.'),
                ]),
                $L('l10', 'Taxes: 8843, FICA and the Substantial Presence Test', "File a federal return every year (Form 1040 or 1040-NR) and the state return where you lived and worked. Nonresident F-1 students file Form 8843 even with no income.\n\n**FICA**: F-1 students who are nonresident aliens for tax purposes - generally the first five calendar years in the U.S. - are exempt from Social Security and Medicare withholding (7.65%). H-1B workers pay it. The **Substantial Presence Test** decides when you become a resident for tax; tell payroll when that happens so the W-4 and FICA are right. Remote work from another state can create a filing there.", [
                    $mc('Who is exempt from FICA withholding?', ['All H-1B workers in their first year', 'F-1 students who are nonresident aliens for tax (usually the first 5 calendar years)', 'Everyone earning under $100,000', 'Nobody'], 1),
                    $fill('The IRS test that decides whether you are a resident for tax purposes is the Substantial ______ Test.', ['presence'], ''),
                ]),
            ]),
        ]],
        // ------------------------------------------------------------------ STEM OPT playbook
        ['id' => 'stem', 't' => 'STEM OPT: the 24-month playbook', 'desc' => 'Everything a STEM OPT consultant has to do and when: the application, the Form I-983 training plan, the six-month validations, the evaluations, unemployment days, job changes, site visits and the route to H-1B - with puzzles to make the dates stick.', 'cat' => 'Compliance', 'level' => 'Essential', 'min' => 35, 'pass' => 80, 'cert' => true, 'req' => [], 'pub' => true, 'mods' => [
            $M('m1', 'Before you apply', [
                $L('l1', 'Are you eligible, and when do you file?', "You qualify for the 24-month extension if:\n\n- your degree is on the DHS STEM Designated Degree Program List (check the CIP code on your I-20) from an accredited, SEVP-certified school;\n- you are on post-completion OPT with a valid EAD;\n- your employer is enrolled in **E-Verify** and signs a **Form I-983** training plan;\n- you have not used a STEM extension for this degree level before (two in a lifetime, for different degrees).\n\n**Timing.** Ask HR for the I-983 about 100 days before your OPT ends. Your DSO issues the STEM OPT I-20 (recommendation); file Form I-765 within **60 days** of that recommendation, no earlier than **90 days** before the EAD expires and **before** it expires. Filed on time, your work authorization continues automatically for up to **180 days** while USCIS decides.\n\nSince the 2026 fixed-admission rule, students whose I-94 end date does not cover the extension also file Form I-539; students admitted under D/S who file by 18 March 2027 are exempt. Confirm with your DSO which applies to you.", [
                    $num('File Form I-765 within how many days of the DSO\'s STEM OPT recommendation on the I-20?', 60),
                    $num('How early (in days before the OPT EAD expires) may the STEM application be filed?', 90),
                    $num('If USCIS has not decided by the EAD expiry, work authorization continues for up to how many days?', 180),
                    $scr('Unscramble the number of the form that carries the training plan.', 'I-983', 'Form I-9?3'),
                ]),
                $L('l2', 'Form I-983 explained', "Form I-983 is the contract between you, your employer and DHS.\n\n- **Section 1-2**: your details and the school.\n- **Section 3-4**: the employer, your site, hours (at least 20 a week), compensation, and the employer's attestations (E-Verify, resources to train you, terms commensurate with U.S. workers, no displacement).\n- **Section 5**: the training plan - specific learning objectives, how they are achieved, your supervisor, and how progress is measured.\n- **Section 6**: employer certification.\n- **Page 5**: the two **evaluations on student progress** (12 months, and the final one).\n\nA **material change** - new employer, new employer address or EIN, new title or duties, a cut in pay not tied to hours, a significant cut in hours, new objectives - needs an amended or new I-983 to your DSO within 10 days. Keep signed copies; DHS asks for them at site visits.", [
                    $multi('Which changes require an amended or new Form I-983? (choose all that apply)', ['New employer', 'Significant reduction in hours', 'A new laptop', 'New supervisor and duties', 'A pay cut not tied to hours'], [0, 1, 3, 4]),
                    $mc('Who signs the evaluations on page 5 of the I-983?', ['Only the student', 'The student and the employer', 'Only the DSO', 'USCIS'], 1),
                ]),
            ]),
            $M('m2', 'The reporting calendar', [
                $L('l3', 'Six-month validations and the two evaluations', "Count from the start date printed on your STEM OPT EAD:\n\n- **6 months** - validation report to the DSO (name, address, employer name and address, still employed). Due within 10 days of the mark; most schools open the window 30 days before.\n- **12 months** - validation **and** the first self-evaluation on I-983 page 5, employer-signed.\n- **18 months** - validation.\n- **24 months** - validation **and** the final evaluation, due within 10 days of the end date. A final evaluation is also due within 10 days whenever you leave an employer.\n\nMissing reports are status violations; after 90 days without reported employer information SEVP terminates the record. The *Compliance* checklist shows each date and lets you tick it off.", [
                    $order('A STEM OPT EAD starts on 1 March 2026. Put these in date order.', ['First validation report (around 1 September 2026)', '12-month validation and self-evaluation (around 1 March 2027)', '18-month validation (around 1 September 2027)', 'Final evaluation (around 1 March 2028)']),
                    $mc('Your STEM EAD started 15 January 2026. The second validation report is due around...', ['15 April 2026', '15 July 2026', '15 January 2027', '15 July 2027'], 2, 'Validations fall at 6, 12, 18 and 24 months: July 2026, January 2027, July 2027, January 2028.'),
                    $tf('If nothing changed since the last report, the six-month validation can be skipped.', false, 'It is due even when nothing changed.'),
                ]),
                $L('l4', 'Unemployment days and job changes', "The aggregate limit is **150 days** across OPT and the STEM extension (90 during post-completion OPT plus 60 more). Each calendar day without a qualifying job counts, including days abroad.\n\nChanging employers:\n\n- The new employer must be E-Verify enrolled and sign a new I-983 before you start.\n- Report the old job's end and the new job within **10 days**; file the final evaluation for the old employer within 10 days.\n- Days between the two jobs are unemployment days - log them in the tracker.\n\nSEVP terminates the record automatically at 150 days.", [
                    $num('You used 40 unemployment days on OPT. How many days remain once you are on the STEM extension?', 110, '150 in aggregate minus 40 used.'),
                    $mc('You leave employer A on a Friday and start employer B the next Monday. How many unemployment days is that?', ['0', '2', '3', '7'], 1, 'Saturday and Sunday count: two days.'),
                    $fill('Before starting with a new STEM OPT employer you need a new signed Form ______.', ['i-983', 'i983'], ''),
                ]),
            ]),
            $M('m3', 'Site visits, employer duties and the road to H-1B', [
                $L('l5', 'When DHS visits', "DHS may visit the worksite, normally with 48 hours' notice, to confirm the training plan is real. Be ready to describe your learning objectives, your supervisor, your duties and how progress is measured - in your own words. The employer shows the I-983, pay records and evidence of E-Verify.\n\nYour employer's side: E-Verify enrolment, the signed plan, 20+ paid hours a week, reporting your departure within 5 business days, and signing the 12- and 24-month evaluations. A staffing or consulting employer must itself provide the supervision and training; a client can host the work, but the plan belongs to the employer.", [
                    $mc('Who must provide the training and supervision described on the I-983 when a consulting company employs you at a client?', ['The client only', 'The consulting employer (the client may host the work)', 'Nobody, the plan is a formality', 'The DSO'], 1),
                    $num('Within how many business days must the employer report that a STEM OPT trainee left?', 5),
                ]),
                $L('l6', 'Towards H-1B', "Plan the H-1B a year before the STEM end date. Registration opens each March; since 2026 the selection is weighted by wage level (Level IV four entries ... Level I one). A selected registration leads to a change-of-status petition; once it is filed while your OPT/STEM OPT is valid, **cap-gap** keeps your status and work authorization until 1 April or the decision. Changing status inside the U.S. also avoids the $100,000 payment that applies to new petitions for people abroad.\n\nNot selected? Cap-exempt employers (universities, non-profit research), O-1 for exceptional profiles, another degree, or simply the remaining STEM months.", [
                    $tf('Changing to H-1B from inside the U.S. avoids the $100,000 payment that targets new petitions for workers abroad.', true),
                    $mc('Cap-gap begins when...', ['you register in the lottery', 'the change-of-status petition is filed while your OPT/STEM OPT is valid and the registration was selected', 'the petition is approved', 'your DSO asks for it'], 1),
                ]),
            ]),
        ]],
        // ------------------------------------------------------------------ CHEA
        ['id' => 'chea', 't' => 'Credentials & accreditation (CHEA)', 'desc' => 'What accreditation is, who recognizes accreditors in the U.S. (CHEA and the Department of Education), how to verify any school or program in minutes, how to spot degree mills and accreditation mills, how foreign degrees are evaluated, and why all of it matters for your visa petitions and your career. Built from the Council for Higher Education Accreditation\'s public resources at chea.org.', 'cat' => 'Credentials', 'level' => 'Essential', 'min' => 40, 'pass' => 70, 'cert' => true, 'req' => ['consultant'], 'pub' => true, 'mods' => [
            $M('m1', 'What accreditation is', [
                $L('l1', 'Accreditation in one page', "In the United States there is no national ministry that licenses universities. Quality is checked by **accreditation**: a voluntary, non-governmental review of colleges, universities and programs by independent accrediting organizations, carried out by academic peers. CHEA calls it \"a major way that students, families, government officials, and the press know that an institution or program provides a quality education\".\n\nTwo kinds:\n\n- **Institutional accreditation** covers a whole college or university. About 19 recognized institutional accreditors operate in the U.S. The old split between \"regional\" and \"national\" accreditors was removed from federal rules in 2020; all are now simply institutional accreditors, though many still carry their historical names (Middle States, HLC, SACSCOC, WSCUC, NECHE, NWCCU...).\n- **Programmatic accreditation** covers a single program or school inside an institution - engineering (ABET), business (AACSB, ACBSP), nursing, law, medicine. About 63 recognized programmatic accreditors exist.\n\nHow it works: the institution writes a **self-study** against the accreditor's standards, a team of **peer reviewers** reads it and makes a **site visit**, the accreditor's commission takes an **action** (accredit, reaffirm, warn, probation, withdraw), and the cycle repeats every few years (reaffirmation, often 5-10 years, with interim reports). Accreditation can be lost.\n\nSource: [CHEA - About accreditation](https://www.chea.org/about-accreditation).", [
                    $mc('Accreditation in the U.S. is...', ['a licence issued by the federal Department of Education', 'a voluntary peer review by non-governmental accrediting organizations', 'a ranking published each year', 'required only for medical schools'], 1),
                    $match('Match the kind of accreditation with what it covers.', [['Institutional accreditation', 'the whole college or university'], ['Programmatic accreditation', 'a single program, such as engineering or business'], ['Reaffirmation', 'the periodic renewal review'], ['Self-study', 'the institution\'s own report against the standards']]),
                    $order('Put the accreditation process in order.', ['The institution writes a self-study against the standards', 'Peer reviewers read it and make a site visit', 'The accrediting commission takes an action', 'Periodic reaffirmation reviews follow']),
                    $tf('The federal government removed the regional-versus-national distinction between institutional accreditors in 2020.', true),
                ]),
            ]),
            $M('m2', 'Who recognizes the accreditors', [
                $L('l2', 'CHEA and the U.S. Department of Education', "Accreditors are themselves reviewed - **recognized** - by two bodies:\n\n- **CHEA**, the Council for Higher Education Accreditation, a non-profit based in Washington, DC, is \"the national voice for accreditation\". It is a membership organization of degree-granting colleges and universities and recognizes accrediting organizations for academic quality, improvement and accountability. Its stated mission: to serve \"its members, students, and society through advocacy for the value and independence of accreditation, recognition of accrediting organizations and commitment to quality in higher education\".\n- The **U.S. Department of Education (USDE)** recognizes accreditors so that their institutions can take part in federal student aid (Title IV). USDE recognition is about federal eligibility; CHEA recognition is about academic quality. Many accreditors hold both.\n\nWhat CHEA offers you:\n\n- the **CHEA Database of Institutions and Programs** accredited by recognized U.S. accreditors - more than 8,200 institutions and 44,000 programs, searchable by name, state and accreditor ([chea.org/directories](https://www.chea.org/directories));\n- the **CHEA International Directory** with quality-assurance bodies from 175 countries;\n- the **CHEA Almanac** with data about accrediting organizations ([almanac.chea.org](https://almanac.chea.org/));\n- the **CHEA International Quality Group (CIQG)** and its International Quality Principles;\n- guides such as \"Ask Before You Decide: Accreditation Matters\" and \"Twelve Important Questions About External Quality Review\".\n\nCHEA never charges individuals for information about accreditation; a request for payment \"from CHEA\" is a scam to report to the FTC.", [
                    $fill('CHEA stands for the Council for Higher Education ______.', ['accreditation']),
                    $mc('Which statement is correct?', ['CHEA accredits universities directly', 'CHEA and the U.S. Department of Education recognize accrediting organizations; the accreditors review the schools', 'Only the Department of Education may recognize accreditors', 'CHEA is a federal agency'], 1),
                    $mc('USDE recognition of an accreditor mainly matters for...', ['federal student aid eligibility (Title IV)', 'sports rankings', 'visa issuance', 'faculty salaries'], 0),
                    $num('Roughly how many institutions are in the CHEA database?', 8200, 'More than 8,200 institutions and 44,000 programs.', 300),
                    $tf('CHEA charges individuals a fee to confirm whether a school is accredited.', false, 'CHEA does not charge or request payment from individuals for accreditation information.'),
                ]),
            ]),
            $M('m3', 'Verify a school or program in minutes', [
                $L('l3', 'The three checks', "Before you enrol, before you list a degree on your resume, and before HR files a petition that relies on a degree, run three checks:\n\n1. **CHEA database** ([chea.org/directories](https://www.chea.org/directories)): search the institution; note the accreditor and whether the accreditation is current. For a program such as engineering or business, look for the programmatic accreditor too.\n2. **USDE's DAPIP** (Database of Accredited Postsecondary Institutions and Programs, [ope.ed.gov/dapip](https://ope.ed.gov/dapip/)): confirms the federal side and shows accreditation actions and dates.\n3. **The accreditor's own directory**: the accreditor's website lists its member institutions and any sanction (warning, probation, show-cause).\n\nAlso check: is the school **SEVP-certified** to enrol F-1 students (Study in the States school search), and is the name exactly right - mills copy famous names with one word changed.\n\n**State authorization is not accreditation.** A school may be licensed by a state to operate without being accredited at all. CHEA's page on \"State Licensed or Authorized Institutions\" explains the difference.", [
                    $multi('Which are legitimate ways to verify accreditation? (choose all that apply)', ['The CHEA database', 'USDE\'s DAPIP database', 'The accreditor\'s own member list', 'A badge on the school\'s homepage'], [0, 1, 2]),
                    $tf('A university licensed by its state to operate is therefore accredited.', false, 'State authorization and accreditation are different things.'),
                    $scr('Unscramble the name of USDE\'s accreditation database.', 'DAPIP', 'Database of Accredited Postsecondary Institutions and Programs'),
                ]),
            ]),
            $M('m4', 'Degree mills and accreditation mills', [
                $L('l4', 'Red flags', "A **degree (diploma) mill** sells degrees with little or no study. An **accreditation mill** sells \"accreditation\" to such schools so they look legitimate. CHEA's fact sheet on the subject lists the warning signs:\n\n**Degree mills**\n- degrees in days or weeks, or for a flat fee rather than per course or credit;\n- degrees for \"life experience\" alone, with no coursework or examinations;\n- little or no contact with faculty; no faculty list, or faculty with degrees from the same mill;\n- a name that resembles a well-known university; an address that is a P.O. box or a suite number;\n- heavy sales pressure, discounts for ordering several degrees, back-dated diplomas.\n\n**Accreditation mills**\n- accreditation granted quickly, for a fee, without a self-study or site visit;\n- institutions allowed to accredit themselves; a list of \"accredited\" schools that includes real universities that never applied;\n- a name that mimics a recognized accreditor; not recognized by CHEA or USDE.\n\nThe test is always the same: is the accreditor on the CHEA or USDE list? If not, the \"accreditation\" means nothing. CHEA and UNESCO have a joint statement on effective practice to discourage degree mills; CHEA's resources are collected at [chea.org/degree-accreditation-mills](https://www.chea.org/degree-accreditation-mills).\n\nWhy it matters to you: USCIS checks degrees in H-1B and green card petitions. A degree from a mill, or an \"evaluation\" that upgrades it, leads to a denial and can be treated as fraud with permanent consequences.", [
                    $multi('Which are red flags for a degree mill? (choose all that apply)', ['A degree granted for life experience alone', 'Tuition charged per course and credit hour', 'A flat fee per degree, delivered in weeks', 'An address that is only a P.O. box', 'A site visit by peer reviewers every few years'], [0, 2, 3]),
                    $mc('An \"accrediting body\" grants accreditation within two weeks for a fee and is on neither the CHEA nor the USDE list. It is most likely...', ['a programmatic accreditor', 'an accreditation mill', 'a state licensing board', 'a CHEA member'], 1),
                    $tf('A degree from an unaccredited school is accepted by USCIS as long as a credential evaluator says it is equivalent.', false, 'Evaluators that upgrade mill degrees are not recognized; USCIS looks at the school\'s accreditation.'),
                ]),
            ]),
            $M('m5', 'Foreign degrees and credential evaluation', [
                $L('l5', 'How a degree from outside the U.S. is read', "CHEA does not evaluate individual degrees; it points to the quality-assurance bodies of other countries in its **International Directory** (175 countries) and, through **CIQG**, to shared quality principles. For an individual's foreign degree, U.S. employers and USCIS rely on **credential evaluation services** - private companies that compare your transcript and degree with U.S. equivalents.\n\n- Use members of **NACES** (National Association of Credential Evaluation Services) or **AICE** (Association of International Credential Evaluators); examples are WES, ECE and SpanTran. Check the member list on the association's website.\n- Ask for the kind of report the purpose needs: a *document-by-document* report for most employers, a *course-by-course* report for further study or licensing.\n- For an H-1B specialty occupation USCIS wants a U.S. bachelor's degree or its equivalent in a specific field. Where the degree is three years, an evaluator may combine it with work experience under the \"three-for-one\" rule (three years of progressive experience for one year of university study), but USCIS gives such combinations more scrutiny - keep experience letters on company letterhead with dates and duties.\n- Your home university must itself be recognized by its national authority; the evaluator checks that first.\n\nUseful sources: [CHEA International Directory](https://www.chea.org/international-directory), [NACES](https://www.naces.org/), [AICE](https://aice-eval.org/).", [
                    $mc('Who evaluates an individual foreign degree for a U.S. employer or USCIS?', ['CHEA', 'A credential evaluation service, preferably a NACES or AICE member', 'The Department of State', 'The accreditor of a U.S. school'], 1),
                    $mc('Under the \"three-for-one\" rule used in H-1B cases...', ['three degrees equal one job', 'three years of progressive work experience may count as one year of university study', 'three evaluations are required', 'one year of work equals three years of study'], 1),
                    $match('Match the report with its usual purpose.', [['Document-by-document evaluation', 'most employers and H-1B petitions'], ['Course-by-course evaluation', 'further study or professional licensing'], ['CHEA International Directory', 'finding a country\'s quality-assurance body'], ['NACES / AICE member lists', 'choosing a legitimate evaluator']]),
                ]),
            ]),
            $M('m6', 'Why it matters for your visa and career', [
                $L('l6', 'Accreditation in your petitions and your resume', "- **F-1 and OPT**: only SEVP-certified schools can enrol you; the STEM extension additionally requires a degree from an **accredited** school. A certificate from an unaccredited \"day-1 CPT\" program can sink a later petition.\n- **H-1B**: the specialty occupation needs a degree in a specific field from an accredited institution or a recognized foreign equivalent.\n- **Green card (EB-2/EB-3)**: the PERM job requirements and your degree must match; evaluations of foreign degrees are examined closely.\n- **Clients and employers** ask whether a program is accredited before paying tuition assistance, evaluating new hires or accepting certifications.\n- **Licensure**: state boards require accredited programs to sit for exams in engineering, accounting, nursing and other fields.\n\nPractical habits: keep official transcripts and degree certificates (and one certified translation if not in English); keep the accreditor's name with each credential in your profile; keep course descriptions for the degree-to-job match; never buy a degree or a \"verification\" online.\n\nCHEA's \"Ask Before You Decide: Accreditation Matters\" guide is a good last read: [chea.org/ask-you-decide-accreditation-matters](https://www.chea.org/ask-you-decide-accreditation-matters).", [
                    $tf('The STEM OPT extension requires that the qualifying degree comes from an accredited, SEVP-certified school.', true),
                    $multi('What should you keep for every degree you list? (choose all that apply)', ['Official transcripts', 'The accreditor\'s name', 'Course descriptions', 'A paid \"verification badge\" from a website'], [0, 1, 2]),
                    $mc('A client asks whether your bootcamp certificate is from an accredited program. The honest answer is...', ['\"Yes\" if the bootcamp has a website', '\"It is a non-accredited certificate\" unless the provider is accredited by a CHEA/USDE-recognized accreditor', '\"Accreditation does not apply to IT\"', '\"Ask CHEA to evaluate it\"'], 1),
                ]),
            ]),
        ]],
        // ------------------------------------------------------------------ Working through StratEdge
        ['id' => 'work', 't' => 'Working through StratEdge: timesheets, pay and policies', 'desc' => 'How the portal runs your week: clock-ins and attendance, weekly timesheets and client approval, paystubs and direct deposit, time off, documents and e-signatures, and the client etiquette that keeps projects renewing.', 'cat' => 'Onboarding', 'level' => 'Starter', 'min' => 25, 'pass' => 70, 'cert' => false, 'req' => ['consultant', 'employee'], 'pub' => true, 'mods' => [
            $M('m1', 'Your week in the portal', [
                $L('l1', 'Attendance and timesheets', "- **Clock in and out** from *Attendance* on the days you work; your location is recorded at clock-in. Forgotten clock-outs can be corrected the same week and go to your manager for approval.\n- **Timesheets** are weekly (Monday to Sunday). Enter hours per day against your assignment, add notes for overtime or holidays, attach the client's timesheet if they use one, and submit by **Friday evening**. The client approves; approved hours drive your pay and the client invoice.\n- A rejected timesheet comes back with a reason - fix and resubmit the same day.\n- Hours on a public holiday or paid time off are entered through *Time off*, not as worked hours.", [
                    $mc('By when should the weekly timesheet be submitted?', ['Monday morning of the next week', 'Friday evening', 'The end of the month', 'Whenever the client asks'], 1),
                    $tf('Approved timesheet hours are what the client is invoiced for and what your pay is based on.', true),
                ]),
                $L('l2', 'Pay, paystubs and direct deposit', "*Earnings* shows every paystub, your pay plan (W-2 hourly or salary, W-2 contract or C2C), direct deposit accounts, W-4 details, benefits and the year-end forms (W-2 or 1099).\n\n- Pay follows the schedule shown on your pay plan; approved hours up to the cut-off are paid in that run.\n- Direct deposit can split between accounts; a new account goes through a prenote (test) first.\n- Check each paystub: gross, deductions, FICA (F-1 nonresident students should see none), state tax for the state you worked in, and PTO balance.\n- Questions go to accounting through *Earnings > Ask about this paystub* or by e-mail.", [
                    $mc('Where do you change your direct deposit account?', ['By e-mailing your bank details to a recruiter', 'In Earnings > Direct deposit (a prenote test follows)', 'On the timesheet', 'You cannot change it'], 1),
                    $multi('What should you check on every paystub? (choose all that apply)', ['Gross pay matches approved hours or salary', 'State tax for the state you worked in', 'FICA, which F-1 nonresident students should not see', 'The font'], [0, 1, 2]),
                ]),
            ]),
            $M('m2', 'Time off, documents and conduct', [
                $L('l3', 'Time off, documents and e-signatures', "- Request **time off** in advance from *Time off*; your manager approves; the client is informed by you in writing as well. Balances appear on the page and the paystub.\n- Upload **documents** (ID, degrees, work authorization, certifications) under *Documents*; HR sees them, nobody else. Immigration documents with expiry dates go in *Compliance > Documents*.\n- Agreements, policy acknowledgements and offer letters arrive under *Sign documents*; sign within the deadline shown. Policies live under *Policies*.\n- Keep your profile (address, phone, emergency contact) current - the same ten-day habit as your immigration address.", [
                    $tf('Immigration documents with expiry dates belong in Compliance > Documents so reminders can be generated.', true),
                    $mc('A policy acknowledgement is waiting in Sign documents. What do you do?', ['Ignore it until HR calls', 'Read and sign it within the deadline shown', 'Print it and mail it', 'Ask the client to sign it'], 1),
                ]),
                $L('l4', 'Client etiquette that gets contracts renewed', "- Be on time, every day, camera on when the team is; announce absences early to the client lead *and* to StratEdge.\n- Never negotiate rates, extensions or conversions directly with the client - route everything through your StratEdge recruiter or account manager (your agreement requires it, and it protects you).\n- Protect client data: no personal e-mail, no personal cloud drives, no code or documents copied out; follow the client's security training.\n- Keep a weekly log of what you delivered; it feeds your resume, your reviews and the live-project vault.\n- Raise problems early - a blocker reported on Monday is a plan; the same blocker on Friday is a missed deadline.", [
                    $mc('The client offers you a direct contract extension at a higher rate. The right move is to...', ['Accept on the spot', 'Thank them and route the conversation through your StratEdge recruiter or account manager', 'Decline', 'Ask the client to keep it secret'], 1),
                    $tf('Copying project code to a personal drive for your portfolio is fine if you remove the client name.', false, 'Client data and code stay with the client; describe the work in your vault instead.'),
                ]),
            ]),
        ]],
        // ------------------------------------------------------------------ Interviews
        ['id' => 'interview', 't' => 'Client interview readiness', 'desc' => 'How client interviews for consulting roles run, how to prepare in two hours, STAR answers that land, technical screens, remote etiquette, questions to ask and the follow-up that closes.', 'cat' => 'Career', 'level' => 'Starter', 'min' => 30, 'pass' => 70, 'cert' => false, 'req' => [], 'pub' => true, 'mods' => [
            $M('m1', 'Prepare', [
                $L('l1', 'The two-hour preparation', "- **Read the requirement again** and mark every skill, tool and domain word; prepare one concrete example for each.\n- **Research the client**: product, industry, recent news, the hiring manager's title; know why the project exists.\n- **Your 90-second introduction**: who you are, the last two projects (problem, your role, the result with a number), why this role.\n- **Six STAR stories** (Situation, Task, Action, Result) covering: a hard bug, a conflict, a deadline, a design decision, a failure you fixed, a time you learned fast.\n- **Logistics**: the link tested, headset charged, a quiet room, your resume and the job description open, water, a notepad.", [
                    $order('Put the STAR components in order.', ['Situation', 'Task', 'Action', 'Result']),
                    $multi('Which belong in a 90-second introduction? (choose all that apply)', ['Your last two projects with a measurable result', 'Why this role interests you', 'Your full salary history', 'Who you are in one line'], [0, 1, 3]),
                ]),
                $L('l2', 'Technical screens and take-homes', "- Think aloud; interviewers grade the reasoning, not only the answer.\n- Clarify requirements before coding; state assumptions; start with the simple version, then improve.\n- For system design: requirements, scale numbers, high-level boxes, data model, the hard part, trade-offs, monitoring.\n- For take-homes: a README with how to run it, tests, a short note on what you would do with more time; submit before the deadline.\n- Never paste client code or data into an interview exercise; use the live projects from this portal as talking material instead.", [
                    $mc('You are asked a design question you have never seen. The best start is...', ['Say you do not know', 'Ask clarifying questions, state assumptions, then sketch the simple version', 'Describe a framework you like', 'Ask to skip it'], 1),
                    $tf('Thinking aloud during a coding screen helps the interviewer evaluate your reasoning.', true),
                ]),
            ]),
            $M('m2', 'Perform and follow up', [
                $L('l3', 'Remote etiquette and the questions you ask', "- Join two minutes early, camera on, neutral background, name shown as on your resume.\n- Answer the question asked, then stop; offer detail if they want it.\n- Three good questions: \"What does success look like in the first 90 days?\", \"What is the hardest part of this project right now?\", \"How does the team review and ship work?\"\n- Do not discuss rate, visa or start date in the technical interview - your recruiter handles those.\n- Afterwards, send your recruiter a summary within the hour: questions asked, how it went, concerns raised. A thank-you note goes through the recruiter unless the client invited direct contact.", [
                    $mc('The interviewer asks about your rate. You should...', ['Quote a number', 'Say your StratEdge recruiter handles rates and steer back to the role', 'Ask for their budget', 'Refuse to answer'], 1),
                    $multi('Good questions to ask at the end (choose all that apply):', ['What does success look like in the first 90 days?', 'What is the hardest part of the project right now?', 'Can I work 20 hours a week instead?', 'How does the team review and ship work?'], [0, 1, 3]),
                ]),
            ]),
        ]],
        // ------------------------------------------------------------------ Portfolio
        ['id' => 'portfolio', 't' => 'Build your portfolio: live projects and the vault', 'desc' => 'How to use the live projects (AI-generated or from the catalog) to practise realistic client work, how to store project evidence in the vault without breaching client confidentiality, and how recruiters use it in submissions.', 'cat' => 'Career', 'level' => 'Starter', 'min' => 15, 'pass' => 70, 'cert' => false, 'req' => [], 'pub' => true, 'mods' => [
            $M('m1', 'Projects and the vault', [
                $L('l1', 'Live projects', "Live projects are realistic, client-style briefs - a problem, users, features, architecture, milestones, acceptance criteria and interview talking points - generated for your target role and stack, or picked from the catalog HR curates.\n\n- Start one from *Live projects*, work through the milestones, tick them off, and upload the result (repository link, screenshots, a short demo) to the vault.\n- Each brief ends with resume bullets you can adapt and the questions an interviewer would ask about it.\n- Keep it honest: a live project is a practice project; describe it as such on your resume (\"Personal project\" or \"Practice engagement\").", [
                    $tf('A live project may be described on your resume as if it were work for a paying client.', false, 'Describe it as a personal or practice project.'),
                ]),
                $L('l2', 'The project vault', "The vault holds evidence of your work: project summaries, architecture notes, sanitized screenshots, certificates, reference letters and links.\n\n- One entry per project or course; add the stack, dates, your role and the outcome with numbers.\n- Never upload client code, data, or documents marked confidential. Describe what you built and the results instead.\n- Tick **Share with recruiters** on entries StratEdge may use in submissions and profile requests; everything else stays private to you and HR.\n- Export your entries as resume bullets when you update your resume.", [
                    $multi('Which may go in the vault? (choose all that apply)', ['A sanitized architecture diagram you drew', 'The client\'s customer database export', 'A certificate', 'A written summary of the outcome with numbers'], [0, 2, 3]),
                    $mc('What does "Share with recruiters" do?', ['Publishes the entry on the website', 'Lets StratEdge recruiters use the entry in submissions; otherwise only you and HR see it', 'E-mails it to clients', 'Nothing'], 1),
                ]),
            ]),
        ]],
    ];
}

